    static class pair{
        long a; 
        long b;
        pair(long x,long y){
            this.a = x;
            this.b = y;
        }
        public boolean equals(Object o) {
            if (o instanceof pair) {
                pair p = (pair)o;
                return p.a == a && p.b == b;
            }
            return false;
        }
        public int hashCode() {
            return (Long.valueOf(a).hashCode())* 31 +(Long.valueOf(b).hashCode());
        }
